insert into patterns (
  slug, platform, category, severity_default, title, description, impact_oneline,
  detector_kind, detector_config, tier_required, remediation_json, fix_prompt, enabled
)
values
  ('bolt-demo-mode-shipped', 'bolt', 'Broken access control', 'high',
   'Bolt demo / skip-auth flag left enabled',
   'Bolt prototypes often include VITE_DEMO_MODE or skipAuth for local testing. When deployed unchanged, the bypass ships to every visitor.',
   'Demo auth bypass from Bolt scaffolding is live in production.',
   'rule_ref',
   '{"rule":"demoModeFlags"}'::jsonb,
   'free',
   '{"summary":"Strip demo flags before deploy.","steps":["Remove VITE_DEMO / skipAuth from client.","Enforce auth on the API layer."]}'::jsonb,
   'My Bolt/Vite app still has demo or skip-auth flags enabled in production. Remove them and enforce authentication on every API call server-side.',
   true),
  ('bolt-public-env-prefix-leak', 'bolt', 'Exposed secret', 'high',
   'Server secret behind a public env prefix',
   'Bolt-generated Vite apps expose any VITE_-prefixed env var to the browser. Secrets accidentally given that prefix are shipped to every visitor.',
   'A secret was exposed because it used a browser-public env prefix.',
   'rule_ref',
   '{"rule":"publicEnvPrefixLeak"}'::jsonb,
   'free',
   '{"summary":"Rename server secrets off the public prefix and rotate them.","steps":["Only VITE_/NEXT_PUBLIC_ values should be browser-safe.","Move secrets to non-public env vars used only server-side, then rotate."]}'::jsonb,
   'A server secret in my Vite/Bolt app is exposed because it uses a VITE_ public prefix. Move it to a non-public server-side variable, update the code to read it server-side only, and tell me to rotate it.',
   true),
  ('client-side-idor-evidence', 'generic', 'Broken access control', 'high',
   'Client bundle documents IDOR-prone API routes',
   'The shipped JavaScript explicitly documents API endpoints that fetch or mutate resources by user-controlled ID without ownership verification — a client-side IDOR anti-pattern even before probing the server.',
   'API routes keyed by user ID lack ownership checks — changing the ID may expose other accounts.',
   'rule_ref',
   '{"rule":"clientSideIdorEvidence"}'::jsonb,
   'deep',
   '{"summary":"Add server-side ownership checks; never trust client-side authorization.","steps":["Verify the authenticated user owns every record on GET/PUT/DELETE.","Remove demo vulnerability markers and mock APIs from production bundles.","Use non-guessable IDs and audit all /api/users/{id} style routes."]}'::jsonb,
   'My client bundle documents IDOR-prone /api/users/{id} routes without ownership checks. Add server-side authorization on every record access and remove vulnerable demo endpoints from production. Show the fixed handlers.',
   true),
  ('client-side-prototype-pollution-evidence', 'generic', 'Injection', 'high',
   'Client bundle documents prototype pollution via __proto__ merge',
   'The shipped HTML/JavaScript merges user-controlled objects without blocking __proto__ or constructor.prototype — enabling prototype pollution that can escalate to RCE in some stacks.',
   'Unsafe object merge allows __proto__ pollution — privilege escalation or RCE may follow.',
   'rule_ref',
   '{"rule":"clientSidePrototypePollutionEvidence"}'::jsonb,
   'deep',
   '{"summary":"Block __proto__ and constructor keys during object merge.","steps":["Use Object.create(null) for lookup maps or a safe merge library.","Reject keys __proto__, constructor, and prototype from user JSON.","Freeze Object.prototype in hardened environments where supported."]}'::jsonb,
   'My app merges user JSON into config objects without blocking __proto__. Add key blocklisting for __proto__/constructor/prototype and show a safe merge helper.',
   true),
  ('client-side-ssrf-evidence', 'generic', 'Server-side request forgery', 'high',
   'Client bundle documents SSRF-prone URL fetch in admin panel',
   'The shipped JavaScript includes SSRF lab markers (e.g. VULNERABILITY: SSRF, localhost blocklist bypass) where user-supplied URLs are fetched server-side without validation.',
   'Admin panels that fetch arbitrary URLs enable SSRF — internal services and cloud metadata may be reachable.',
   'rule_ref',
   '{"rule":"clientSideSsrfEvidence"}'::jsonb,
   'deep',
   '{"summary":"Block internal IPs, metadata endpoints, and file:// schemes before server-side fetch.","steps":["Allowlist outbound fetch destinations; deny RFC1918, link-local, and metadata IPs.","Never pass raw user URLs to server-side fetch without DNS rebinding protections.","Remove SSRF demo code and vulnerability markers from production bundles."]}'::jsonb,
   'My admin panel fetches user-supplied URLs server-side (SSRF risk). Add URL allowlisting, block private/metadata IPs, and show the safe fetch handler.',
   true),
  ('client-side-file-upload-evidence', 'generic', 'Broken access control', 'critical',
   'Client bundle documents unsafe file upload without validation',
   'The shipped JavaScript advertises file upload with no type or size validation (e.g. VULNERABILITY: No file type validation), enabling arbitrary file upload to admin panels.',
   'Unrestricted file upload can lead to webshell deployment and full server compromise.',
   'rule_ref',
   '{"rule":"clientSideFileUploadEvidence"}'::jsonb,
   'deep',
   '{"summary":"Validate MIME type, extension, and size server-side; store uploads outside webroot.","steps":["Allowlist safe extensions and verify magic bytes server-side.","Enforce max file size and scan uploads with AV where possible.","Store uploads on object storage with no execute permission."]}'::jsonb,
   'My app uploads files without type validation (VULNERABILITY: No file type validation). Add server-side MIME/extension allowlisting, size limits, and store uploads outside the webroot.',
   true),
  ('sensitive-api-token-leakage', 'generic', 'Sensitive data exposure', 'high',
   'JWT or session token returned in unauthenticated API response',
   'A JSON API endpoint returns a JWT or session token (e.g. token field with eyJ...) without requiring authentication — leaking secrets to any caller.',
   'Session tokens in public API responses let attackers hijack accounts or read privileged data.',
   'rule_ref',
   '{"rule":"sensitiveApiTokenLeakage"}'::jsonb,
   'deep',
   '{"summary":"Never return session tokens in public API bodies; use HttpOnly cookies.","steps":["Remove token fields from unauthenticated GET responses.","Store session tokens in HttpOnly Secure cookies, not JSON bodies.","Remove DEBUG token console.log statements from production bundles."]}'::jsonb,
   'My /api/posts (or similar) returns a JWT in the JSON body without auth. Remove token fields from public responses, use HttpOnly cookies for sessions, and delete debug token logging.',
   true),
  ('client-side-session-hijack-evidence', 'generic', 'Broken authentication', 'high',
   'Client bundle documents session hijack / token replay',
   'The shipped HTML/JavaScript walks through session token theft and replay (e.g. doReplay, vault-token UI) — indicating cookies lack HttpOnly/Secure or session fixation is possible.',
   'Session tokens can be stolen and replayed — MFA does not protect against cookie theft.',
   'rule_ref',
   '{"rule":"clientSideSessionHijackEvidence"}'::jsonb,
   'deep',
   '{"summary":"Set HttpOnly + Secure + SameSite on session cookies; enable server-side revocation.","steps":["Add HttpOnly and Secure flags to all session/auth cookies.","Use SameSite=Lax or Strict to limit cross-site cookie sending.","Rotate session IDs on login and support server-side session revocation."]}'::jsonb,
   'My app is vulnerable to session hijack (session tokens can be stolen and replayed). Configure session cookies with HttpOnly, Secure, and SameSite=Lax, rotate session IDs on login, and add server-side session revocation. Show the cookie/session config.',
   true),
  ('client-side-sql-evidence', 'generic', 'Injection', 'high',
   'Client bundle builds SQL via string concatenation',
   'The shipped JavaScript constructs SQL queries by concatenating user input into SELECT/WHERE clauses, or simulates classic SQLi bypass checks (e.g. '' or ''1''=''1). When wired to a real database this is trivially injectable.',
   'SQL is built from user strings in the browser — classic injection if the query reaches a database.',
   'rule_ref',
   '{"rule":"clientSideSqlEvidence"}'::jsonb,
   'deep',
   '{"summary":"Use parameterized queries; never concatenate user input into SQL.","steps":["Replace string-concat SQL with prepared statements / ORM parameter binding.","Remove client-side SQL simulation and auth bypass string checks from production.","Validate and escape all user input server-side before it touches a query."]}'::jsonb,
   'My client bundle concatenates user input into SQL (SELECT ... WHERE id = ''" + input). Replace with parameterized queries server-side and remove unsafe string-concat query builders from the shipped JavaScript.',
   true),
  ('client-side-csrf-evidence', 'generic', 'Broken access control', 'high',
   'Client bundle documents CSRF-vulnerable transfer flows',
   'The shipped JavaScript exposes attack/secure mode CSRF labs, unverified token warnings, or simulated forged transfer requests — cross-site request forgery is likely on state-changing endpoints.',
   'CSRF protections are disabled or documented as bypassable — attackers can forge bank transfers and account actions.',
   'rule_ref',
   '{"rule":"clientSideCsrfEvidence"}'::jsonb,
   'deep',
   '{"summary":"Enforce CSRF tokens on every state-changing request; validate Origin/Referer.","steps":["Issue per-session CSRF tokens and require them on POST/PUT/DELETE.","Set SameSite=Lax or Strict on session cookies.","Remove CSRF attack simulation and vulnerable-mode toggles from production bundles."]}'::jsonb,
   'My banking app bundle documents CSRF-vulnerable transfer flows with attack/secure mode toggles. Add server-side CSRF token validation on every state-changing endpoint, set SameSite cookies, and remove CSRF lab demo code from production.',
   true),
  ('ssti-template-injection', 'generic', 'Injection', 'critical',
   'Server-side template injection (SSTI) confirmed via arithmetic probe',
   'A GET parameter is injected into a server-side template engine. Probing with 7*7 returns 49 in the rendered output — positive proof the template evaluates attacker-controlled expressions.',
   'SSTI often escalates to remote code execution — template engines can invoke OS commands.',
   'rule_ref',
   '{"rule":"sstiTemplateInjection"}'::jsonb,
   'deep',
   '{"summary":"Never pass user input into template expressions; use logic-less templates or strict sandboxing.","steps":["Render templates with a logic-less engine or pass user data only as bound variables.","Disable dangerous template helpers (eval, exec, include) in production.","Add input validation and output encoding before any template render path."]}'::jsonb,
   'My app evaluates user input inside server-side templates (7*7 renders as 49). Stop passing raw query parameters into template expressions, use bound variables only, and show the safe render handler.',
   true),
  ('client-side-xor-auth-evidence', 'generic', 'Broken authentication', 'high',
   'Client-side XOR/obfuscated credential check in browser JS',
   'The shipped JavaScript validates login by XORing username:password against a hardcoded ciphertext blob with a static key — authentication is entirely client-side and bypassable in DevTools.',
   'Client-side auth checks are trivially bypassed — anyone can forge credentials without server validation.',
   'rule_ref',
   '{"rule":"clientSideXorAuthEvidence"}'::jsonb,
   'deep',
   '{"summary":"Move all authentication to the server; never compare credentials in browser JavaScript.","steps":["Remove client-side login validation and XOR/cipher comparison logic from production bundles.","Validate credentials server-side with bcrypt/argon2 and issue HttpOnly session cookies.","Never ship encryption keys or expected credential blobs to the browser."]}'::jsonb,
   'My login uses client-side xorString() to compare credentials against an encrypted blob with a hardcoded key. Move authentication to the server, remove XOR checks from the bundle, and show the secure login API handler.',
   true),
  ('client-side-nosql-evidence', 'generic', 'Injection', 'high',
   'Client bundle documents NoSQL injection via MongoDB operators',
   'The shipped JavaScript constructs MongoDB findOne queries with user-supplied JSON objects or documents NoSQL operator injection ($gt, $ne) that bypass authentication.',
   'NoSQL queries built from user JSON objects — auth bypass and data exfiltration if wired to MongoDB.',
   'rule_ref',
   '{"rule":"clientSideNosqlEvidence"}'::jsonb,
   'deep',
   '{"summary":"Sanitize MongoDB query inputs; reject operator keys starting with $.","steps":["Use mongo-sanitize or schema validation to strip $ operator keys from user input.","Never pass raw req.body objects directly to findOne/find without type coercion.","Remove NoSQL injection demo code and educational lab markers from production bundles."]}'::jsonb,
   'My client bundle documents NoSQL injection via MongoDB $gt/$ne operator objects in findOne queries. Add mongo-sanitize, validate login input as strings only, and show the safe Mongoose/MongoDB query handler.',
   true),
  ('client-side-xxe-evidence', 'generic', 'Injection', 'high',
   'Client bundle documents XXE via external entity expansion',
   'The shipped HTML/JavaScript documents XML External Entity attacks — file:// entity payloads, libxmljs parsing without noent/nonet hardening, or DOMParser text/xml usage.',
   'XXE entity expansion can read local files or reach internal URLs — critical if XML parsing is server-side.',
   'rule_ref',
   '{"rule":"clientSideXxeEvidence"}'::jsonb,
   'deep',
   '{"summary":"Disable external entity processing in all XML parsers.","steps":["Set libxmljs/DOMParser options: noent=false, nonet=true, dtdload=false.","Reject DOCTYPE declarations and external entities in user-supplied XML.","Remove XXE demo payloads and educational lab markers from production."]}'::jsonb,
   'My app parses user-supplied XML with external entity support (XXE risk). Disable entity expansion, block DOCTYPE/external entities, and show the hardened libxmljs or DOMParser configuration.',
   true),
  ('client-side-api-security-lab-evidence', 'generic', 'Broken access control', 'high',
   'Client bundle documents OWASP API Security Top 10 lab',
   'The shipped HTML/JavaScript advertises deliberately vulnerable REST APIs covering OWASP API Security Top 10 categories — BOLA, BFLA, broken authentication, and related API authorization flaws.',
   'API routes documented without object/function-level authorization — BOLA and BFLA likely on production endpoints.',
   'rule_ref',
   '{"rule":"clientSideApiSecurityLabEvidence"}'::jsonb,
   'deep',
   '{"summary":"Enforce object-level and function-level authorization on every API route.","steps":["Verify the authenticated user owns every object on GET/PUT/DELETE.","Check role/permission before admin or privileged function endpoints.","Remove deliberately vulnerable API lab documentation from production bundles."]}'::jsonb,
   'My API lacks object-level authorization (BOLA) and function-level checks (BFLA). Add ownership validation on every /api/{resource}/{id} route and role checks on admin endpoints. Show the fixed middleware.',
   true),
  ('convex-open-query-no-auth', 'generic', 'Broken access control', 'critical',
   'Convex query returns data without authentication',
   'Every Convex query is exposed at POST /api/query on your deployment URL. AI-built apps frequently ship list/get queries without an auth check, so anyone who finds your deployment URL in the bundle can read user data.',
   'Anonymous callers can read your Convex database through an unauthenticated query.',
   'rule_ref',
   '{"rule":"convexOpenQuery","options":{"harmlessProbe":true}}'::jsonb,
   'free',
   '{"summary":"Add ctx.auth.getUserIdentity() checks to every public Convex query.","steps":["Audit every query in your convex/ folder for missing auth checks.","Throw or return null when ctx.auth.getUserIdentity() is absent on sensitive queries.","Use internalQuery for server-only functions and keep public queries owner-scoped.","Re-test by calling POST /api/query without an Authorization header."]}'::jsonb,
   'My Convex deployment has queries that return data without authentication. Audit every query function, add ctx.auth.getUserIdentity() checks on sensitive reads, scope results to the authenticated user, and show the updated code for each fixed query.',
   true),
  ('cors-reflect-origin', 'generic', 'Security misconfiguration', 'high',
   'CORS reflects arbitrary Origin',
   'The server echoes whatever Origin header the browser sends in Access-Control-Allow-Origin. Any malicious site can therefore read credentialed API responses from a victim''s browser session.',
   'Any website can read authenticated cross-origin API responses.',
   'rule_ref',
   '{"rule":"corsReflectOrigin"}'::jsonb,
   'free',
   '{"_raw":"{ summary: \"Stop reflecting Origin; use an explicit allow-list.\", steps: [ \"Replace dynamic Origin reflection with a fixed allow-list of trusted domains.\", \"Never combine reflected origins with Access-Control-Allow-Credentials: true unless the allow-list is strict.\", \"Return no CORS headers for unknown origins.\" ] }"}'::jsonb,
   'My API reflects the request Origin header in Access-Control-Allow-Origin. Replace this with an explicit allow-list of trusted origins and show me the middleware/config change.',
   true),
  ('cursor-next-public-secret', 'cursor', 'Exposed secret', 'critical',
   'NEXT_PUBLIC_ variable holds a server secret',
   'Cursor/Claude-generated Next.js apps often put API keys in NEXT_PUBLIC_* because the model copies .env examples. Anything with that prefix is embedded in the browser bundle.',
   'A server secret was published under a NEXT_PUBLIC_ name.',
   'rule_ref',
   '{"rule":"publicEnvPrefixLeak"}'::jsonb,
   'free',
   '{"summary":"Rename secrets off NEXT_PUBLIC_ and rotate them.","steps":["Only publish truly public values with NEXT_PUBLIC_.","Read secrets in route handlers / server components only."]}'::jsonb,
   'My Next.js app exposes a server secret via a NEXT_PUBLIC_ env var. Move it to a server-only env var, update all reads to server-side code, and tell me to rotate the key.',
   true),
  ('dangerous-html-sinks', 'generic', 'Cross-site scripting', 'high',
   'Dangerous HTML sinks in client bundle',
   'The shipped JavaScript uses bypassSecurityTrustHtml, dangerouslySetInnerHTML, or dynamic innerHTML bindings with API/user data — bypassing XSS sanitization. Stored or reflected XSS becomes trivial.',
   'User-controlled data is rendered as HTML — XSS can steal sessions.',
   'rule_ref',
   '{"rule":"dangerousHtmlSinks"}'::jsonb,
   'free',
   '{"summary":"Never mark user/API content as trusted HTML; encode or sanitize.","steps":["Remove bypassSecurityTrustHtml / dangerouslySetInnerHTML on dynamic data.","Render user content as text nodes or through a strict sanitizer.","Add CSP without unsafe-inline in production."]}'::jsonb,
   'My Angular/React bundle uses bypassSecurityTrustHtml or dangerouslySetInnerHTML with dynamic data (orderId, searchValue, etc.). Remove trusted-HTML rendering on user/API content and show the safe template change.',
   true),
  ('directory-listing-enabled', 'generic', 'Information disclosure', 'medium',
   'Directory listing (autoindex) is enabled',
   'A directory returns an auto-generated file index instead of a page, letting anyone browse and download every file it contains — often uploads, backups, or build artifacts.',
   'Anyone can browse and download the files in an exposed directory.',
   'rule_ref',
   '{"rule":"directoryListing"}'::jsonb,
   'free',
   '{"summary":"Disable directory autoindex on your web server / host.","steps":["Turn off autoindex/directory listing at the server or CDN level.","Serve an index file or return 403/404 for directory paths.","Move private files (uploads, backups) out of the public web root."]}'::jsonb,
   'My site has directory listing enabled on one or more folders. Disable autoindex so directories don''t list their contents, and move any private files out of the public web root. Show me the config.',
   true),
  ('dom-eval-xss', 'generic', 'Cross-site scripting', 'high',
   'DOM XSS via eval() on user input',
   'The shipped JavaScript passes DOM input (getElementById/querySelector .value) directly to eval() or new Function(). Any attacker-controlled string executes as code in the victim''s browser.',
   'User input is executed via eval() — full session compromise via crafted input.',
   'rule_ref',
   '{"rule":"domEvalXss"}'::jsonb,
   'free',
   '{"summary":"Remove eval() and new Function() on any user-influenced string.","steps":["Delete eval()/new Function() calls that read from DOM inputs.","Parse structured data with JSON.parse and validate with a schema.","Render user content as text, never as executable code."]}'::jsonb,
   'My client bundle calls eval() or new Function() on DOM input (.value from getElementById/querySelector). Remove dynamic code execution, parse input safely, and show the fixed handler.',
   true),
  ('exposed-config-backup', 'generic', 'Exposed secret', 'critical',
   'Config or backup file reachable over HTTP',
   'A configuration, credential, or database-backup file is served directly from the web root. AI deploy scaffolds routinely leave these in the published artifact, exposing connection strings, API keys, and full data dumps.',
   'A config/backup file with secrets or data is downloadable by anyone.',
   'http_probe',
   '{"paths":["/.env.development","/.env.backup","/config.json","/appsettings.json","/credentials.json","/.npmrc","/docker-compose.yml","/database.sql","/dump.sql","/backup.sql","/db.sqlite","/.DS_Store"],"expect":{"kind":"body_regex","regex":"(=|:|\\bBEGIN\\b|INSERT INTO|CREATE TABLE|\"[a-z_]+\"\\s*:)"},"maxBytes":4096}'::jsonb,
   'free',
   '{"summary":"Stop serving config/backup files from the web root and rotate anything they exposed.","steps":["Remove config, credential, and *.sql/backup files from the deployed artifact and web root.","Add host deny rules for dotfiles and *.sql / *.sqlite / *.json config paths.","Rotate every credential any exposed file contained."]}'::jsonb,
   'My deployed site serves config/backup files (e.g. config.json, dump.sql, .env.*) over HTTP. Ensure these are never included in the deployed web root, add deny rules for them, and list which secrets I must rotate.',
   true),
  ('exposed-env-file', 'generic', 'Exposed secret', 'critical',
   'Environment file reachable over HTTP',
   'A .env file is served by the production deploy. These files hold database URLs, API keys and signing secrets. AI scaffolds frequently leave them inside the deployed web root.',
   'Your .env file (all your secret keys) is downloadable by anyone.',
   'http_probe',
   '{"paths":["/.env","/.env.local","/.env.production","/api/.env"],"expect":{"kind":"body_regex","regex":"[A-Z0-9_]+="},"maxBytes":4096}'::jsonb,
   'free',
   '{"summary":"Stop serving .env and rotate every secret it contained.","steps":["Move .env outside the deployed web root and add it to your ignore/deny rules.","Rotate every credential the file contained.","Add a deny rule for dotfiles in your host config."]}'::jsonb,
   'My deployed site serves my .env file over HTTP. Stop it from being publicly served, ensure .env is excluded from the deploy/web root, and list every secret it contained so I can rotate them.',
   true),
  ('exposed-git-dir', 'generic', 'Source exposure', 'high',
   'Exposed .git directory',
   'The .git directory is reachable, which lets anyone reconstruct your full source history including any secrets committed along the way.',
   'Your full source code and its history can be downloaded.',
   'http_probe',
   '{"_raw":"{ paths: [\"/.git/HEAD\", \"/.git/config\"], expect: { kind: \"body_regex\", regex: \"ref:|\\\\[core\\\\]\" }, maxBytes: 2048 }"}'::jsonb,
   'free',
   '{"summary":"Stop serving the .git directory from your production host.","steps":["Exclude .git from the deployed artifact / web root.","Add a host rule denying access to /.git.","Audit history for any committed secrets and rotate them."]}'::jsonb,
   'My production deploy exposes the /.git directory. Make sure .git is never deployed or served, add a deny rule for it, and check whether any secrets were committed to history.',
   true),
  ('exposed-infra-artifacts', 'generic', 'Exposed secret', 'critical',
   'Infrastructure artifact reachable over HTTP',
   'DevOps and platform config files (Terraform state, AWS credentials, Spring Boot actuator env, kubeconfig, Fly.io config, WordPress/Django settings) are served from the web root. Misconfigured static hosts and CI deploys routinely publish these alongside the app, leaking cloud keys and database passwords.',
   'Terraform state, AWS creds, or actuator env is downloadable — full cloud takeover.',
   'rule_ref',
   '{"rule":"exposedInfraArtifacts"}'::jsonb,
   'free',
   '{"summary":"Remove infra artifacts from the deployed web root and rotate every exposed credential.","steps":["Delete terraform.tfstate, .aws/credentials, kubeconfig, and settings backups from the public artifact.","Disable Spring Boot actuator endpoints in production or restrict them to internal networks.","Rotate every cloud key, database password, and API token any exposed file contained."]}'::jsonb,
   'My production deploy serves infrastructure files (terraform.tfstate, .aws/credentials, actuator/env, fly.toml, kubeconfig, or settings.py) over HTTP. Remove them from the web root, block those paths at the edge, disable actuator in production, and list every secret I must rotate.',
   true),
  ('exposed-source-maps', 'generic', 'Source exposure', 'medium',
   'Source maps published to production',
   'JavaScript source maps are served in production, exposing your original (pre-minified) source. The default AI builder template often does not strip them.',
   'Your original source code is readable in the browser.',
   'rule_ref',
   '{"rule":"sourceMaps"}'::jsonb,
   'free',
   '{"summary":"Disable source map emission for production builds.","steps":["Turn off productionBrowserSourceMaps / build.sourcemap in your config.","Re-deploy and confirm .map files 404."]}'::jsonb,
   'My production build publishes JavaScript source maps. Disable production source maps in the build config and confirm the .map files are no longer served.',
   true),
  ('firebase-config-exposed', 'firebase', 'Information exposure', 'info',
   'Firebase web config present in bundle',
   'The Firebase web config (apiKey, projectId, etc.) is intentionally public, but its presence tells an attacker to test your security rules. This is informational unless rules are open.',
   'Reveals your Firebase project so attackers can probe its rules. Safe only if rules are locked down.',
   'secret_regex',
   '{"regex":"AIza[0-9A-Za-z_\\-]{35}","secretName":"Firebase web API key"}'::jsonb,
   'free',
   null,
   '',
   true),
  ('firebase-open-firestore-rules', 'firebase', 'Broken access control', 'critical',
   'Firestore / Realtime DB rules left open',
   'AI builders commonly ship the Firebase quickstart rules `allow read, write: if true;`. Combined with the public web config, anyone can read and write your entire database.',
   'Anyone on the internet can read and overwrite your database.',
   'rule_ref',
   '{"rule":"firebaseRules","options":{"harmlessProbe":true}}'::jsonb,
   'free',
   '{"summary":"Replace permissive rules with auth- and ownership-scoped rules.","steps":["Open the Firebase console > Firestore/Realtime Database > Rules.","Remove any `if true` allow rule.","Require request.auth != null and scope documents to request.auth.uid."]}'::jsonb,
   'My Firebase security rules are open (allow read, write: if true). Rewrite the Firestore (and Realtime Database, if present) rules so reads/writes require authentication and are scoped to the document owner via request.auth.uid. Output the complete rules file.',
   true),
  ('graphql-introspection-enabled', 'generic', 'Information disclosure', 'medium',
   'GraphQL introspection is enabled in production',
   'A public GraphQL endpoint answers introspection queries, handing attackers a complete map of your schema — every type, query, and mutation, including internal ones. Auto-generated GraphQL layers (Hasura, Apollo, Postgraphile) ship with it on by default.',
   'Your full GraphQL schema (incl. internal mutations) is readable by anyone.',
   'rule_ref',
   '{"rule":"graphqlIntrospection"}'::jsonb,
   'free',
   '{"_raw":"{ summary: \"Disable introspection in production and lock down the GraphQL endpoint.\", steps: [ \"Turn off introspection in your GraphQL server''s production config.\", \"Require authentication/authorization on the GraphQL endpoint.\", \"Disable any built-in GraphQL playground/IDE in production.\" ] }"}'::jsonb,
   'My production GraphQL endpoint allows introspection. Disable introspection and any GraphQL playground in production, and require auth on the endpoint. Show me the config for my server.',
   true),
  ('idor-sequential-ids', 'generic', 'Broken access control', 'high',
   'Object access by predictable sequential IDs (IDOR)',
   'AI-generated CRUD scaffolding often exposes resources by sequential numeric IDs without an ownership check, so changing the ID in the URL returns another user''s data.',
   'Changing an ID in the URL may expose other users'' private records.',
   'rule_ref',
   '{"rule":"idorObjectAccess"}'::jsonb,
   'deep',
   '{"summary":"Add server-side ownership checks to every record lookup.","steps":["On every fetch/update/delete, verify the record belongs to the authenticated user.","Prefer non-guessable IDs (UUIDs) for user-facing resources.","Add automated tests that attempt cross-account access."]}'::jsonb,
   'My API may have IDOR: records are fetched by sequential ID without checking ownership. Add server-side ownership checks to every record access and switch user-facing IDs to UUIDs. Show the updated handlers.',
   true),
  ('jwt-alg-none-accepted', 'generic', 'Broken authentication', 'critical',
   'JWT "none" algorithm accepted on API route',
   'An API route that requires authentication accepts a forged unsigned JWT with alg:none. This lets anyone mint valid-looking tokens without the signing secret — full account takeover.',
   'Attackers can forge JWTs with alg:none and impersonate any user, including admins.',
   'rule_ref',
   '{"rule":"jwtAlgNoneProbe"}'::jsonb,
   'deep',
   '{"summary":"Pin JWT verification to a specific algorithm and reject alg:none.","steps":["Configure your JWT library to allow only HS256/RS256 (never ''none'').","Verify the algorithm from the token header matches your expected value.","Add a test that rejects unsigned alg:none tokens."]}'::jsonb,
   'My API accepts JWTs with alg:"none", letting attackers forge tokens. Pin verification to HS256/RS256, explicitly reject alg:none, and show me the middleware/library config change.',
   true),
  ('inline-state-secrets', 'generic', 'Exposed secret', 'critical',
   'Server secrets embedded in the page''s inline app state',
   'Live server credentials are shipped inside the page''s inline JSON state (Next.js __NEXT_DATA__, or a window.__ENV__/__CONFIG__ bootstrap object). AI builders commonly pass server config straight into page props, so the secret is readable in View Source.',
   'A server key is sitting in your page''s HTML — visible in View Source.',
   'rule_ref',
   '{"rule":"inlineStateSecrets"}'::jsonb,
   'free',
   '{"summary":"Keep server secrets server-side; never pass them into client props or global state.","steps":["Remove secret values from getServerSideProps/getStaticProps output and any window.__ENV__ object.","Access server secrets only in server code (route handlers, server actions), never in props.","Rotate every credential that appeared in the page state."]}'::jsonb,
   'My page ships server secrets inside its inline app state (__NEXT_DATA__ / window.__ENV__). Move those values to server-only code so they never reach the client, and list the secrets I need to rotate.',
   true),
  ('insecure-cookies', 'generic', 'Security misconfiguration', 'medium',
   'Cookies set without the Secure flag',
   'One or more cookies are set over HTTPS without the Secure attribute, so the browser will also send them over plain HTTP where they can be intercepted. Session cookies additionally missing HttpOnly are readable by injected JavaScript.',
   'Session/auth cookies can leak over HTTP or be stolen via XSS.',
   'rule_ref',
   '{"rule":"insecureCookies"}'::jsonb,
   'free',
   '{"summary":"Set Secure, HttpOnly and SameSite on session/auth cookies.","steps":["Add the Secure attribute to every cookie so it is only sent over HTTPS.","Add HttpOnly to session/auth cookies so JavaScript cannot read them.","Set SameSite=Lax (or Strict) to reduce CSRF exposure."]}'::jsonb,
   'My site sets cookies without the Secure flag (and some without HttpOnly/SameSite). Update my cookie configuration so session/auth cookies are Secure, HttpOnly and SameSite=Lax, and show me the config.',
   true),
  ('lovable-client-only-auth', 'lovable', 'Broken access control', 'high',
   'Client-side-only route guarding (auth not enforced on data)',
   'Lovable scaffolds frequently gate UI routes in React but leave the Supabase/data layer open, so the API/DB can be hit directly without the UI ever loading.',
   'Hiding a page in the UI does not protect the data behind it; the data is still reachable.',
   'rule_ref',
   '{"rule":"clientOnlyAuth"}'::jsonb,
   'deep',
   '{"summary":"Enforce authorization at the data layer, not just the UI.","steps":["Add Row Level Security / server-side checks for every table and endpoint.","Treat client route guards as UX only, never as security."]}'::jsonb,
   'My app guards routes in the React UI but the underlying Supabase data is reachable without auth. Add server-side / RLS authorization on every table and endpoint so data is protected independently of the UI.',
   true),
  ('lovable-supabase-storage-public', 'lovable', 'Broken access control', 'high',
   'Lovable scaffold left a public Supabase Storage bucket',
   'Lovable templates default to a public avatars/uploads bucket. Without storage RLS, anyone with the anon key from your bundle can list and fetch objects.',
   'Public storage is a common Lovable default — user files may be world-readable.',
   'rule_ref',
   '{"rule":"supabaseStoragePublic"}'::jsonb,
   'free',
   '{"summary":"Lock down storage buckets and add RLS.","steps":["Set buckets to private.","Add storage.objects RLS.","Re-test with the anon key."]}'::jsonb,
   'My Lovable app has a public Supabase storage bucket. Make buckets private and add storage RLS policies so only the owning user can access their files.',
   true),
  ('missing-security-headers', 'generic', 'Security misconfiguration', 'medium',
   'Critical security headers missing',
   'Core security headers (Content-Security-Policy, X-Frame-Options, Strict-Transport-Security) are absent. Default Vite/Next templates produced by AI builders rarely set them.',
   'Missing headers leave you open to clickjacking and protocol-downgrade attacks.',
   'rule_ref',
   '{"rule":"securityHeaders"}'::jsonb,
   'free',
   '{"_raw":"{ summary: \"Add CSP, X-Frame-Options and HSTS to your responses.\", steps: [ \"Set Strict-Transport-Security with a long max-age.\", \"Set X-Frame-Options: DENY (or frame-ancestors in CSP).\", \"Add a Content-Security-Policy starting from a restrictive baseline.\" ] }"}'::jsonb,
   'My site is missing Content-Security-Policy, X-Frame-Options and Strict-Transport-Security headers. Add them in my framework config with sensible secure defaults and show me the config.',
   true),
  ('open-redirect-query-param', 'generic', 'Broken access control', 'medium',
   'Open redirect via query parameter',
   'A URL query parameter (e.g. ?next=, ?redirect=, ?return=) accepts an arbitrary external destination and the server issues an HTTP redirect to it. AI-generated login and OAuth flows commonly ship this pattern for post-auth navigation without validating the target.',
   'Attackers can craft links that redirect victims to phishing sites after visiting your domain.',
   'rule_ref',
   '{"rule":"openRedirect"}'::jsonb,
   'free',
   '{"summary":"Allow-list redirect destinations; never redirect to arbitrary URLs from query params.","steps":["Replace open redirects with an allow-list of same-origin paths (or known trusted hosts).","Reject absolute URLs unless the host is explicitly trusted.","Prefer relative paths only (e.g. /dashboard) for post-login navigation."]}'::jsonb,
   'My app has an open redirect: a query parameter like ?next= or ?redirect= sends users to arbitrary external URLs. Add an allow-list so only same-origin (or explicitly trusted) destinations are permitted, and show me the updated redirect handler.',
   true),
  ('permissive-cors', 'generic', 'Security misconfiguration', 'medium',
   'CORS allows any origin',
   'The response sets Access-Control-Allow-Origin: *, letting any website read cross-origin responses. Combined with Allow-Credentials this exposes authenticated data to any site.',
   'Any website can read cross-origin responses from this endpoint.',
   'rule_ref',
   '{"rule":"permissiveCors"}'::jsonb,
   'free',
   '{"_raw":"{ summary: \"Replace the wildcard with an explicit allow-list of trusted origins.\", steps: [ \"Set Access-Control-Allow-Origin to specific trusted origins, not ''*''.\", \"Never combine a wildcard origin with Allow-Credentials: true.\", \"Reflect only origins from an allow-list you control.\" ] }"}'::jsonb,
   'My API returns Access-Control-Allow-Origin: *. Replace the wildcard CORS policy with an explicit allow-list of trusted origins and make sure credentials are never allowed with a wildcard. Show me the config.',
   true),
  ('phpinfo-exposed', 'generic', 'Information disclosure', 'high',
   'PHP phpinfo() page reachable in production',
   'A phpinfo() diagnostic page is publicly reachable. It dumps PHP version, loaded extensions, server paths, and often environment variables — a goldmine for attackers planning further exploits.',
   'Anyone can read your full PHP/server configuration via phpinfo().',
   'rule_ref',
   '{"rule":"phpinfoExposed"}'::jsonb,
   'free',
   '{"summary":"Delete phpinfo pages from production and block the paths at the server.","steps":["Remove phpinfo.php / info.php from the deployed web root.","Return 404 for /phpinfo* paths in your server or WAF rules.","Rotate any secrets that may have appeared in phpinfo environment output."]}'::jsonb,
   'My production server still serves phpinfo.php (or similar). Remove those diagnostic files from the web root, block the paths in production, and show me the server config change.',
   true),
  ('reflected-xss-query-param', 'generic', 'Cross-site scripting', 'high',
   'Reflected XSS via query parameter',
   'A search or filter query parameter is echoed unescaped in the HTML response body. Attackers can craft links that execute JavaScript in victims'' browsers when clicked.',
   'A URL parameter is reflected as raw HTML — session theft via crafted links is likely.',
   'rule_ref',
   '{"rule":"reflectedXss"}'::jsonb,
   'deep',
   '{"summary":"HTML-encode all user input before rendering; use framework auto-escaping.","steps":["Encode dynamic output in HTML contexts (use framework escaping, never raw concatenation).","Add a strict Content-Security-Policy without unsafe-inline.","Validate and reject HTML metacharacters on input where possible."]}'::jsonb,
   'My app reflects query parameters unescaped in HTML (reflected XSS). HTML-encode all dynamic output, remove raw string concatenation in templates, and add a strict CSP. Show the fixed handler/template.',
   true),
  ('replit-exposed-dot-replit', 'replit', 'Source exposure', 'medium',
   'Replit project config reachable over HTTP',
   'A deployed Replit app sometimes serves .replit or replit.nix, revealing run commands and internal layout.',
   'Project config files are downloadable from production.',
   'http_probe',
   '{"paths":["/.replit","/replit.nix","/.config/replit"],"expect":{"kind":"status_2xx_non_html"},"maxBytes":4096}'::jsonb,
   'free',
   '{"summary":"Stop serving Replit config files from the public web root.","steps":["Exclude .replit and nix configs from the static deploy.","Confirm they 404."]}'::jsonb,
   'My Replit deploy serves .replit or similar config files. Exclude them from the public web root and confirm they return 404.',
   true),
  ('replit-secrets-in-client', 'replit', 'Exposed secret', 'critical',
   'Replit secret referenced in client-side code',
   'Replit Secrets are meant for server-side use. AI-generated frontends often read process.env / import.meta.env in the browser, shipping those secrets to visitors.',
   'Secrets from Replit may be readable in the browser bundle.',
   'rule_ref',
   '{"rule":"publicEnvPrefixLeak"}'::jsonb,
   'free',
   '{"summary":"Use Replit Secrets only in backend/server code.","steps":["Move secret reads into Express/FastAPI/server routes.","Rotate any secret that appeared in client JS."]}'::jsonb,
   'My Replit app may be exposing Secrets in client-side code. Find every client reference to secrets/env vars, move them server-side, and list what I must rotate.',
   true),
  ('robots-sensitive-paths', 'generic', 'Information disclosure', 'medium',
   'robots.txt discloses sensitive paths',
   'The published robots.txt file lists Disallow paths that reveal admin panels, backups, or internal routes — a free map for attackers.',
   'robots.txt advertises admin/backup paths attackers can probe.',
   'rule_ref',
   '{"rule":"robotsSensitivePaths"}'::jsonb,
   'free',
   '{"_raw":"{ summary: \"Remove sensitive paths from robots.txt or block them at the edge.\", steps: [ \"Delete Disallow entries that name admin, backup, or config paths.\", \"Protect sensitive routes with auth regardless of robots.txt.\", \"Use noindex meta tags for pages you don''t want indexed instead of advertising paths.\" ] }"}'::jsonb,
   'My robots.txt lists sensitive paths like /admin or /backup. Rewrite it to avoid disclosing internal routes, and show me how to protect those paths with auth instead.',
   true),
  ('secret-anthropic', 'generic', 'Exposed secret', 'high',
   'Anthropic API key exposed in client bundle',
   'An Anthropic API key (sk-ant-*) was found in JavaScript or HTML served to the browser, and a harmless read against Anthropic''s Models API confirmed the key is active. AI scaffolds routinely ship ANTHROPIC_API_KEY via NEXT_PUBLIC_* or VITE_* env vars.',
   'Your Anthropic key can be abused to bill your account.',
   'rule_ref',
   '{"rule":"anthropicLiveKeyProbe"}'::jsonb,
   'free',
   '{"summary":"Rotate the Anthropic API key now and move it server-side.","steps":["Revoke and create a new API key in the Anthropic console immediately.","Remove ANTHROPIC_API_KEY from all client code and client-exposed env vars (NEXT_PUBLIC_*, VITE_*).","Call Anthropic only from server-side code (route handlers / serverless functions)."]}'::jsonb,
   'An Anthropic API key is exposed in my client bundle and validated as active. Remove it from all client-side code and client-exposed environment variables, move every Anthropic call into server-side code, and tell me exactly which files referenced it so I can rotate the key.',
