   '{"regex":"rk_live_[A-Za-z0-9]{20,}","secretName":"Stripe restricted key","serverOnly":true}'::jsonb,
   'free',
   '{"summary":"Rotate the Stripe restricted key now and move it server-side.","steps":["Treat the key as compromised and rotate it with the provider immediately.","Remove it from all client code and from any client-exposed env var (e.g. NEXT_PUBLIC_*, VITE_*).","Access the key only from server-side code (route handlers / serverless functions)."]}'::jsonb,
   'A Stripe restricted key is exposed in my client bundle. Remove it from all client-side code and client-exposed environment variables, move every use of it into server-side code, and tell me exactly which files referenced it so I can rotate and confirm.',
   true),
  ('secret-supabase-service-role', 'generic', 'Exposed secret', 'critical',
   'Supabase service_role JWT exposed in client bundle',
